"""Measured round4 status; narrow string-copy diagnostics are not knowledge accuracy."""
import json,hashlib
from pathlib import Path
root=Path(__file__).resolve().parents[1]
def read(p):return json.loads((root/p).read_text())
s={'round':4,'total_rounds':6,'next_round':5,'date':'2026-11-13','entry':read('eval/round4-entry-state.json'),'training_processes_finished':True,'knowledge_accepted':False,'general_multiturn_accepted':False,'physical_board_accepted':False,'windows_interaction_tested':False,'default_model_replaced':False,'profiles':{},'utf8_regression':read('eval/round4-utf8-regression-summary.json'),'primitive_checks':read('eval/round4-primitives.json'),'synthetic_rollback':read('eval/round4-forced-rollback.json')}
for p in ['n16','n32']:
 m=root/f'models/{p}-multiturn-round4';i=read(f'eval/round4-{p}-context-int8.json');f=read(f'eval/round4-{p}-context-fp32kv.json');old=read(f'eval/round4-{p}-baseline-context-int8.json');k=read(f'eval/round4-{p}-knowledge-regression.json');c=read(f'eval/round4-{p}-context-challenge.json')
 fw=root/f'firmware/.pio/build/{"n16r8" if p=="n16" else "n32r16"}/firmware.bin'
 s['profiles'][p]={'training':read(f'models/{p}-multiturn-round4/summary.json'),'selected_local_step':read(f'models/{p}-multiturn-round4/final/checkpoint_meta.json')['step'],'fp32_sha256':hashlib.sha256((m/'final/model.safetensors').read_bytes()).hexdigest(),'baseline_context_exact':old['exact_whole_answer_matches'],'context_exact':i['exact_whole_answer_matches'],'context_total':len(i['rows']),'reset_context_exact':i['reset_exact_matches'],'fp32kv_context_exact':f['exact_whole_answer_matches'],'kv_same_final_answers':sum(x['turns'][-1]['answer']==y['turns'][-1]['answer'] for x,y in zip(i['rows'],f['rows'])),'exploratory_challenge_exact':c['exact_whole_answer_matches'],'challenge_total':len(c['rows']),'knowledge_regression_rows':len(k['rows']),'invalid_utf8':sum(not x.get('utf8_valid',True) for x in k['rows']),'numerics_pass':read(f'eval/round4-{p}-numerics.json')['pass'],'layout':read(f'eval/round4-{p}-layout.json'),'tokenizer_roundtrip':read(f'eval/round4-{p}-tokenizer-development.json')['hanzi_roundtrip'],'tokenizer_parity':read(f'eval/round4-{p}-tokenizer-development.json')['tokenizer_hf_parity'],'http_pass':read(f'eval/web-http-{p}-multiturn-q4-round4.json')['pass'],'firmware_bytes':fw.stat().st_size,'firmware_sha256':hashlib.sha256(fw.read_bytes()).hexdigest(),'actual_q4_boundary_checks':read(f'eval/round4-{p}-utf8-boundaries.json')}
