(root/'eval/round4-status.json').write_text(json.dumps(s,ensure_ascii=False,indent=2));print({p:{k:v[k] for k in ['context_exact','reset_context_exact','exploratory_challenge_exact','invalid_utf8','firmware_bytes']} for p,v in s['profiles'].items()})
